#!/usr/bin/env node
/**
 * Writes `.env.local` for local development from the running Supabase stack.
 *
 * `.env.example` documents every value, but four of them are generated by
 * `supabase start` and two more are only needed in production. Copying the
 * example and "filling in the values" means pasting two long JWTs by hand,
 * which is the step people get wrong — and a wrong anon key fails as a blank
 * screen rather than as an error that names it.
 *
 * Refuses to overwrite an existing file: a real `.env.local` may hold keys for
 * a hosted project, and losing those to a convenience script is not a trade
 * worth making.
 */

import { execFileSync } from 'node:child_process'
import { existsSync, writeFileSync } from 'node:fs'

const TARGET = '.env.local'

if (existsSync(TARGET)) {
  console.error(`${TARGET} already exists. Delete it first if you want it rewritten.`)
  process.exit(1)
}

let status
try {
  status = JSON.parse(execFileSync('supabase', ['status', '-o', 'json'], { encoding: 'utf8' }))
} catch {
  console.error('Could not read the local Supabase stack. Run `pnpm db:start` first.')
  process.exit(1)
}

if (!status.ANON_KEY || !status.SERVICE_ROLE_KEY || !status.API_URL) {
  console.error(
    'The Supabase stack is up but reported no keys. Try `pnpm db:stop && pnpm db:start`.',
  )
  process.exit(1)
}

// Resend is not reached in local development. Supabase delivers the one-time
// code to Mailpit, and `EMAIL_TRANSPORT=mailpit` sends everything the
// application writes itself to the same place — so an invitation or a
// cancellation e-mail is readable at http://127.0.0.1:54324 while it is being
// worked on, instead of vanishing into an unreachable API.
writeFileSync(
  TARGET,
  [
    `NEXT_PUBLIC_SUPABASE_URL=${status.API_URL}`,
    `NEXT_PUBLIC_SUPABASE_ANON_KEY=${status.ANON_KEY}`,
    'NEXT_PUBLIC_SITE_URL=http://127.0.0.1:3000',
    `SUPABASE_SERVICE_ROLE_KEY=${status.SERVICE_ROLE_KEY}`,
    'RESEND_API_KEY=not-used-in-local-development',
    'EMAIL_TRANSPORT=mailpit',
    'AUTH_SENDER_EMAIL=trainlio@example.test',
    'CRON_SECRET=local-development-secret-value',
    '',
  ].join('\n'),
)

console.log(
  `Wrote ${TARGET}. Sign-in codes arrive at ${status.MAILPIT_URL ?? 'http://127.0.0.1:54324'}`,
)
